-- ============================================================================
-- Rehébergement des photos produit (audit AdSense) : 476 fiches du catalogue
-- électronique pointaient leur image_url directement vers les sites sources
-- (Soumari.com / Electromenager-Dakar.com / Promo.sn) — hotlink vers un domaine
-- concurrent, dépendance externe fragile, signal de contenu non originalisé.
-- Ce script bascule image_url (et images[]) vers les photos déjà présentes en
-- local (dossier product_photos/, une par produit) uploadées sur le bucket
-- Supabase Storage nexus-images (products/catalogue-electronique/<id>.<ext>).
-- 2 fiches caméra Hikvision sans photo locale correspondante restent inchangées
-- (à traiter séparément).
--
-- v2 : UPDATE...FROM (VALUES...) en une seule instruction (pas de table
-- temporaire) — le pooler Supabase peut exécuter des instructions top-level
-- séparées sur des connexions différentes, ce qui faisait disparaître la
-- table temporaire créée dans une instruction précédente ("relation does not
-- exist"). Une seule instruction élimine ce problème.
-- Idempotent : rejouer ce script réapplique juste les mêmes URLs.
-- ============================================================================

update public.products p
set image_url = v.image_url,
    images = array[v.image_url]
from (values
